# Project ARA: Reborn - mod installer (generated by tools\make_release.py from this template).
# Usage: double-click INSTALL.bat, or:  powershell -ExecutionPolicy Bypass -File install.ps1 [-GamePath "...\Ara History Untold"]@@PARAMDOC@@
param([string]$GamePath = ""@@PARAMS@@)
$ErrorActionPreference = 'Stop'
$ModName   = '@@NAME@@'
$ProxyDll  = '@@PROXY@@'          # game DLL replaced by the mod (the original is kept as <name>_orig.dll and still used)
$Marker    = '@@MARKER@@'         # forwarder text that only exists in the mod's DLL (any version), so it is never mistaken for the original
$DataDir   = '@@DATA@@'           # folder under Documents\My Games\Ara History Untold\Mods (empty = none)
$Here      = Split-Path -Parent $MyInvocation.MyCommand.Path

function Find-Game {
    if ($GamePath -and (Test-Path (Join-Path $GamePath 'bin\AraHistoryUntold.exe'))) { return (Resolve-Path $GamePath).Path }
    $libs = @()
    foreach ($k in @(@('HKCU:\Software\Valve\Steam', 'SteamPath'), @('HKLM:\SOFTWARE\WOW6432Node\Valve\Steam', 'InstallPath'))) {
        try { $v = (Get-ItemProperty -Path $k[0] -Name $k[1] -ErrorAction Stop).($k[1]); if ($v) { $libs += $v } } catch {}
    }
    foreach ($s in @($libs)) {
        $vdf = [IO.Path]::Combine($s, 'steamapps', 'libraryfolders.vdf')
        if (Test-Path -LiteralPath $vdf -ErrorAction SilentlyContinue) { foreach ($m in [regex]::Matches((Get-Content $vdf -Raw), '"path"\s+"([^"]+)"')) { $libs += $m.Groups[1].Value.Replace('\\', '\') } }
    }
    foreach ($l in $libs) {
        $g = [IO.Path]::Combine($l, 'steamapps', 'common', 'Ara History Untold')   # Combine: a library on a missing drive does not break the search
        try { if (Test-Path -LiteralPath ([IO.Path]::Combine($g, 'bin', 'AraHistoryUntold.exe'))) { return $g } } catch {}
    }
    throw 'ARA: History Untold was not found. Run again with -GamePath "C:\path\Ara History Untold".'
}
function Has-Marker([string]$file, [string]$text) {
    return [Text.Encoding]::ASCII.GetString([IO.File]::ReadAllBytes($file)).Contains($text)
}

$game = Find-Game
$bin = Join-Path $game 'bin'
Write-Host "Game: $game"
if (Get-Process AraHistoryUntold -ErrorAction SilentlyContinue) { throw 'Close the game before installing.' }

# 1) proxy DLL
$target = Join-Path $bin $ProxyDll
$orig = Join-Path $bin ($ProxyDll -replace '\.dll$', '_orig.dll')
if (-not (Test-Path $orig)) {
    if (-not (Test-Path $target)) { throw "$ProxyDll was not found in the game's bin folder." }
    if (Has-Marker $target $Marker) { throw "$ProxyDll is already the mod's DLL but the original ($([IO.Path]::GetFileName($orig))) is missing. Use Steam's 'Verify integrity of game files' and install again." }
    Rename-Item $target ([IO.Path]::GetFileName($orig))
    Write-Host "Original kept as: $([IO.Path]::GetFileName($orig))"
} elseif ((Test-Path $target) -and -not (Has-Marker $target $Marker)) {
    Copy-Item $target $orig -Force          # Steam restored the original DLL (verify/update): it becomes the new _orig
    Write-Host 'Steam had restored the original DLL; the _orig copy was updated.'
}
Copy-Item (Join-Path $Here "bin\$ProxyDll") $target -Force
Write-Host "Installed: bin\$ProxyDll"

# 2) mod data
if ($DataDir) {
    $mods = Join-Path ([Environment]::GetFolderPath('MyDocuments')) 'My Games\Ara History Untold\Mods'
    New-Item -ItemType Directory -Force $mods | Out-Null
    Copy-Item (Join-Path $Here "data\$DataDir") $mods -Recurse -Force
    Write-Host "Installed: Mods\$DataDir (enable the mod when starting a NEW game: game rules are stored in the save)"
}
@@EXTRA@@
Write-Host ''
Write-Host "$ModName installed. Log and settings files are in: $bin" -ForegroundColor Green
